import {canonicalSha256} from '../core/canonical-json.mjs';
export const HARNESS_EVENTS=Object.freeze(['session.created','session.resumed','before.prompt.submit','before.tool.execute','after.tool.execute','before.file.write','after.file.write','before.mcp.execute','after.mcp.execute','before.agent.delegate','after.agent.complete','verification.checkpoint','session.compact','session.ended']);
export async function runHarnessEvent({event,payload={},rules=[],hooks=[],action}={}){if(!HARNESS_EVENTS.includes(event))throw new TypeError(`Unsupported harness event: ${event}`);const decisions=[];for(const rule of [...rules].sort((a,b)=>a.id.localeCompare(b.id))){const matched=Boolean(await rule.predicate({event,payload}));if(matched)decisions.push({id:rule.id,decision:rule.decision??'deny'});}const denied=decisions.find(x=>x.decision==='deny');if(denied){const error=new Error(`Harness event denied by rule ${denied.id}`);error.code='HARNESS_RULE_DENIED';throw error;}const hookResults=[];for(const hook of [...hooks].filter(x=>x.event===event).sort((a,b)=>a.id.localeCompare(b.id)))hookResults.push({id:hook.id,result:await hook.run({event,payload})});const output=typeof action==='function'?await action({event,payload}):null;const subject={schemaVersion:1,event,payloadSha256:canonicalSha256(payload),decisions,hookResults,output};return Object.freeze({...subject,status:'completed',eventReceiptSha256:canonicalSha256(subject)});}
